import base64

B58 = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz"
def b58decode(s):
    n = 0
    for c in s:
        n = n * 58 + B58.index(c)
    return n.to_bytes((n.bit_length() + 7) // 8, "big")

CODECS = {0x55: "raw", 0x70: "dag-pb", 0x71: "dag-cbor"}
HASHES = {0x12: "sha2-256", 0x13: "sha2-512", 0x1e: "blake3"}

def b32(b):  # base32 RFC 4648 minuscolo senza padding
    return base64.b32encode(b).decode().lower().rstrip("=")

def unb32(s):
    s = s.upper()
    return base64.b32decode(s + "=" * (-len(s) % 8))

def v0_to_v1(cid0, codec=0x70):
    mh = b58decode(cid0)
    return "b" + b32(bytes([0x01, codec]) + mh)   # 'b' = prefisso multibase base32

def inspect(cid):
    if cid.startswith("Qm"):
        mh, version, codec, base = b58decode(cid), 0, 0x70, "base58btc (implicita)"
    elif cid[0] == "b":
        raw = unb32(cid[1:])
        version, codec, mh, base = raw[0], raw[1], raw[2:], "base32"
    else:
        raise ValueError("multibase non gestita")
    return (f"{base} - cidv{version} - {CODECS[codec]} - "
            f"({HASHES[mh[0]]} : {mh[1]*8} : {mh[2:].hex().upper()})")

v0 = "QmbWqxBEKC3P8tqsKc98xmWNzrzDtRLMiMPL8wBuTGsMnR"
v1 = v0_to_v1(v0)
print(v1)
print(v1 == "bafybeigdyrzt5sfp7udm7hu76uh7y26nf3efuylqabf3oclgtqy55fbzdi")
print(inspect(v0))
print(inspect(v1))
print("stesso hash, codec raw:     ", v0_to_v1(v0, 0x55)[:10], "...")
print("stesso hash, codec dag-cbor:", v0_to_v1(v0, 0x71)[:10], "...")

