codeExercises.solution:
import hashlib

def varint_encode(n: int) -> bytes:
    out = bytearray()
    while True:
        b = n & 0x7F
        n >>= 7
        if n:
            out.append(b | 0x80)   # bit alto a 1: seguono altri byte
        else:
            out.append(b)
            return bytes(out)

def varint_decode(buf: bytes, i=0):
    n = shift = 0
    while True:
        b = buf[i]; i += 1
        n |= (b & 0x7F) << shift
        if b < 0x80:
            return n, i
        shift += 7

CODES = {"sha2-256": 0x12, "sha2-512": 0x13, "sha3-256": 0x16, "sha3-512": 0x14,
         "blake2b-256": 0xb220, "sha1": 0x11}
NAMES = {v: k for k, v in CODES.items()}
IMPL = {"sha2-256": hashlib.sha256, "sha2-512": hashlib.sha512, "sha3-256": hashlib.sha3_256,
        "sha3-512": hashlib.sha3_512, "sha1": hashlib.sha1,
        "blake2b-256": lambda d: hashlib.blake2b(d, digest_size=32)}

def multihash(data: bytes, name: str) -> bytes:
    d = IMPL[name](data).digest()
    return varint_encode(CODES[name]) + varint_encode(len(d)) + d

def parse(mh: bytes):
    code, i = varint_decode(mh)
    length, i = varint_decode(mh, i)
    digest = mh[i:]
    assert len(digest) == length, "lunghezza incoerente"
    return NAMES[code], length, digest

def verify(data: bytes, mh: bytes) -> bool:
    name, _, digest = parse(mh)          # la funzione si legge dalla multihash stessa
    return IMPL[name](data).digest() == digest

data = b"hello IPFS"
for name in ["sha2-256", "sha3-512", "blake2b-256"]:
    mh = multihash(data, name)
    n, l, d = parse(mh)
    print(f"{name:12s} prefisso={mh[:len(mh)-l].hex():8s} len={l:2d} totale={len(mh)} byte  ok={verify(data, mh)}")
print("verify su dati alterati:", verify(b"hello IPFs", multihash(data, "sha2-256")))
print("varint(0xb220) =", varint_encode(0xb220).hex())

